-- Sprint 17C.47 owner-preserving read-only reconciliation.
BEGIN TRANSACTION READ ONLY;
DO $fid_acl_017c47$
DECLARE
  setting_name constant text:='lbht.fid_acl_017c47_reconciliation'; fid_schema_oid oid; owner_oid oid; service_oid oid; anon_oid oid; authenticated_oid oid; function_oid oid; function_count integer; metadata_ref regclass; metadata_count bigint; object_count integer;
  direct_public integer; direct_anon integer; direct_authenticated integer; direct_owner integer; direct_service integer; direct_total integer; grantable_total integer; owner_match boolean; security_match boolean; search_path_match boolean; volatility_match boolean; parallel_match boolean;
  effective_public boolean; effective_anon boolean; effective_authenticated boolean; effective_owner boolean; effective_service boolean; owner_derived boolean; evidence_complete boolean; before_exact boolean; after_exact boolean; partial_exact boolean; invariant_conflict boolean; classification text;
BEGIN
  PERFORM pg_catalog.set_config(setting_name,'{"sentinel":"PENDING"}',true);
  SELECT oid INTO fid_schema_oid FROM pg_catalog.pg_namespace WHERE nspname='fid'; SELECT oid INTO owner_oid FROM pg_catalog.pg_roles WHERE rolname='fid_function_owner'; SELECT oid INTO service_oid FROM pg_catalog.pg_roles WHERE rolname='service_role'; SELECT oid INTO anon_oid FROM pg_catalog.pg_roles WHERE rolname='anon'; SELECT oid INTO authenticated_oid FROM pg_catalog.pg_roles WHERE rolname='authenticated';
  SELECT count(*)::integer,(array_agg(p.oid))[1] INTO function_count,function_oid FROM pg_catalog.pg_proc p JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='fid' AND p.proname='fid_execute_atomic_persistence_batch' AND pg_catalog.pg_get_function_identity_arguments(p.oid)='batch_id text, ordered_operations jsonb, requested_atomicity text, preconditions jsonb, expected_repository jsonb, idempotency jsonb, audit jsonb, source_refs jsonb';
  metadata_ref:=pg_catalog.to_regclass('fid.fid_persistence_migrations')::regclass; IF metadata_ref IS NOT NULL THEN EXECUTE pg_catalog.format('SELECT count(*) FROM %s WHERE migration_id COLLATE "C" LIKE %L OR migration_sequence=14 OR %L=ANY(applied_migration_ids)',metadata_ref,'%014%','fid-014-identifier-issuance-transaction') INTO metadata_count; END IF;
  SELECT count(*)::integer INTO object_count FROM (VALUES(pg_catalog.to_regclass('fid.fid_identifier_reservations')::oid),(pg_catalog.to_regclass('fid.fid_identifier_issuance_ledger')::oid),(pg_catalog.to_regclass('fid.fid_identifier_issuance_idempotency')::oid),(pg_catalog.to_regprocedure('fid.fid_execute_prospect_identifier_issuance_transaction(text,text,text,text,text,text,text,text,text,text,text,text,text,text,text,integer,text,text,text,jsonb,jsonb)')::oid)) objects(object_oid) WHERE object_oid IS NOT NULL;
  IF function_count=1 AND function_oid IS NOT NULL THEN SELECT p.proowner=owner_oid,p.prosecdef,p.proconfig=ARRAY['search_path=pg_catalog, fid']::text[],p.provolatile='v',p.proparallel='u' INTO owner_match,security_match,search_path_match,volatility_match,parallel_match FROM pg_catalog.pg_proc p WHERE p.oid=function_oid; END IF;
  IF function_count=1 AND function_oid IS NOT NULL AND owner_oid IS NOT NULL AND service_oid IS NOT NULL AND anon_oid IS NOT NULL AND authenticated_oid IS NOT NULL THEN
    SELECT count(*) FILTER(WHERE a.grantee=0 AND a.privilege_type='EXECUTE'),count(*) FILTER(WHERE a.grantee=anon_oid AND a.privilege_type='EXECUTE'),count(*) FILTER(WHERE a.grantee=authenticated_oid AND a.privilege_type='EXECUTE'),count(*) FILTER(WHERE a.grantee=owner_oid AND a.privilege_type='EXECUTE'),count(*) FILTER(WHERE a.grantee=service_oid AND a.privilege_type='EXECUTE'),count(*) FILTER(WHERE a.privilege_type='EXECUTE'),count(*) FILTER(WHERE a.privilege_type='EXECUTE' AND a.is_grantable) INTO direct_public,direct_anon,direct_authenticated,direct_owner,direct_service,direct_total,grantable_total FROM pg_catalog.pg_proc p CROSS JOIN LATERAL pg_catalog.aclexplode(COALESCE(p.proacl,pg_catalog.acldefault('f',p.proowner))) a WHERE p.oid=function_oid;
    effective_public:=direct_public>0; effective_anon:=pg_catalog.has_function_privilege(anon_oid,function_oid,'EXECUTE'); effective_authenticated:=pg_catalog.has_function_privilege(authenticated_oid,function_oid,'EXECUTE'); effective_owner:=pg_catalog.has_function_privilege(owner_oid,function_oid,'EXECUTE'); effective_service:=pg_catalog.has_function_privilege(service_oid,function_oid,'EXECUTE'); owner_derived:=owner_match IS TRUE AND effective_owner IS TRUE;
  END IF;
  evidence_complete:=fid_schema_oid IS NOT NULL AND owner_oid IS NOT NULL AND service_oid IS NOT NULL AND anon_oid IS NOT NULL AND authenticated_oid IS NOT NULL AND function_count=1 AND function_oid IS NOT NULL AND metadata_ref IS NOT NULL AND metadata_count IS NOT NULL AND object_count IS NOT NULL;
  before_exact:=direct_public=1 AND direct_anon=0 AND direct_authenticated=0 AND direct_owner=1 AND direct_service=0 AND direct_total=2 AND grantable_total=0 AND effective_public AND effective_anon AND effective_authenticated AND effective_owner AND effective_service AND owner_derived;
  after_exact:=direct_public=0 AND direct_anon=0 AND direct_authenticated=0 AND direct_owner=1 AND direct_service=1 AND direct_total=2 AND grantable_total=0 AND NOT effective_public AND NOT effective_anon AND NOT effective_authenticated AND effective_owner AND effective_service AND owner_derived;
  partial_exact:=direct_anon=0 AND direct_authenticated=0 AND direct_owner=1 AND direct_public IN(0,1) AND direct_service IN(0,1) AND direct_total=direct_public+direct_owner+direct_service AND grantable_total=0 AND effective_owner AND owner_derived AND effective_public=(direct_public>0) AND effective_anon=(direct_public>0) AND effective_authenticated=(direct_public>0) AND effective_service=(direct_public>0 OR direct_service>0);
  invariant_conflict:=object_count<>0 OR metadata_count<>0 OR owner_match IS NOT TRUE OR security_match IS NOT TRUE OR search_path_match IS NOT TRUE OR volatility_match IS NOT TRUE OR parallel_match IS NOT TRUE OR grantable_total<>0 OR direct_owner<>1 OR direct_anon<>0 OR direct_authenticated<>0 OR direct_total<>COALESCE(direct_public,0)+COALESCE(direct_anon,0)+COALESCE(direct_authenticated,0)+COALESCE(direct_owner,0)+COALESCE(direct_service,0);
  classification:=CASE WHEN NOT evidence_complete THEN 'FID_ATOMIC_FUNCTION_ACL_REMEDIATION_STATE_UNRESOLVED' WHEN invariant_conflict THEN 'FID_ATOMIC_FUNCTION_ACL_REMEDIATION_STATE_INCONSISTENT_RECOVERY_REQUIRED' WHEN before_exact THEN 'FID_ATOMIC_FUNCTION_ACL_REMEDIATION_FULLY_UNAPPLIED' WHEN after_exact THEN 'FID_ATOMIC_FUNCTION_ACL_REMEDIATION_FULLY_APPLIED' WHEN partial_exact THEN 'FID_ATOMIC_FUNCTION_ACL_REMEDIATION_PARTIALLY_APPLIED' ELSE 'FID_ATOMIC_FUNCTION_ACL_REMEDIATION_TARGET_STATE_BLOCKED' END;
  PERFORM pg_catalog.set_config(setting_name,pg_catalog.jsonb_build_object('result_identity','FID_ATOMIC_FUNCTION_ACL_OWNER_PRESERVING_RECONCILIATION_017C47','result_version','17C.47.1','mode','RECONCILIATION','classification',classification,'function_identity_resolution_count',function_count,'function_owner_match',owner_match,'security_definer_match',security_match,'search_path_match',search_path_match,'volatility_match',volatility_match,'parallel_safety_match',parallel_match,'public_direct_execute',direct_public>0,'anon_direct_execute',direct_anon>0,'authenticated_direct_execute',direct_authenticated>0,'owner_direct_acl_entry',direct_owner>0,'service_direct_execute',direct_service>0,'public_effective_execute',effective_public,'anon_effective_execute',effective_anon,'authenticated_effective_execute',effective_authenticated,'owner_effective_execute',effective_owner,'owner_derived_authority',owner_derived,'service_effective_execute',effective_service,'metadata_storage_present',metadata_ref IS NOT NULL,'migration_014_metadata_count',metadata_count,'migration_014_object_count',object_count,'evidence_complete',evidence_complete,'external_target_attestation_required',true,'overall_target_verified',false,'read_only',true,'mutation_count',0)::text,true);
END
$fid_acl_017c47$;
SELECT r.* FROM pg_catalog.jsonb_to_record(pg_catalog.current_setting('lbht.fid_acl_017c47_reconciliation',true)::jsonb) AS r(result_identity text,result_version text,mode text,classification text,function_identity_resolution_count integer,function_owner_match boolean,security_definer_match boolean,search_path_match boolean,volatility_match boolean,parallel_safety_match boolean,public_direct_execute boolean,anon_direct_execute boolean,authenticated_direct_execute boolean,owner_direct_acl_entry boolean,service_direct_execute boolean,public_effective_execute boolean,anon_effective_execute boolean,authenticated_effective_execute boolean,owner_effective_execute boolean,owner_derived_authority boolean,service_effective_execute boolean,metadata_storage_present boolean,migration_014_metadata_count bigint,migration_014_object_count integer,evidence_complete boolean,external_target_attestation_required boolean,overall_target_verified boolean,read_only boolean,mutation_count integer);
COMMIT;
